// packages/core/test/vectors.spec.ts
//
// Golden test: every row of specs/test-vectors.json is re-computed through
// the public runtime API and compared byte-for-byte. The vector file is
// generated by scripts/generate-vectors.ts (PLAN-LTS-v1.md PR-3, BL-20).
// Any deviation means a breaking protocol change — the vector file, the
// spec (specs/v1.0.md) and the CHANGELOG must move together.

import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import {
  Identity,
  Attestation,
  Handle,
  Session,
  get64ByteSeedFromMnemonic,
} from '../src/index.js';
import { base64urlEncode, base64urlDecode } from '../src/util.js';

const file = readFileSync(
  new URL('../../../specs/test-vectors.json', import.meta.url),
  'utf8'
);
const doc = JSON.parse(file) as {
  spec: string;
  spec_version: string;
  vectors: Record<string, Record<string, unknown>[]>;
};

const hex = (b: Uint8Array): string => Buffer.from(b).toString('hex');
const fromHex = (h: string): Uint8Array => new Uint8Array(Buffer.from(h, 'hex'));

describe('specs/test-vectors.json golden test', () => {
  it('is a v1.0 core-protocol vector file', () => {
    expect(doc.spec).toBe('Me2eM core protocol');
    expect(doc.spec_version).toBe('1.0');
  });

  describe('seed (BIP39 → 64 bytes)', () => {
    for (const [i, v] of (doc.vectors.seed ?? []).entries()) {
      it(`row ${i}: ${v.description}`, async () => {
        const seed = await get64ByteSeedFromMnemonic(
          v.mnemonic as string,
          v.passphrase as string
        );
        expect(seed.length).toBe(64);
        expect(hex(seed)).toBe(v.expected_seed_hex);
      });
    }
  });

  describe('identity_derivation', () => {
    for (const [i, v] of (doc.vectors.identity_derivation ?? []).entries()) {
      it(`row ${i}: ${v.description}`, async () => {
        const identity = await Identity.fromSeed(fromHex(v.seed_hex as string));
        expect(hex(identity.getPublicKey())).toBe(v.expected_public_key_hex);
      });
    }
  });

  describe('handle_derivation', () => {
    for (const [i, v] of (doc.vectors.handle_derivation ?? []).entries()) {
      it(`row ${i}: ${v.description}`, async () => {
        const identity = await Identity.fromSeed(fromHex(v.seed_hex as string));
        const handle = await identity.deriveHandle(v.handle_name as string);
        expect(hex(handle.getPublicKey())).toBe(v.expected_public_key_hex);
        expect(handle.getId()).toBe(v.expected_id_b64url);
      });
    }
  });

  describe('subhandle_derivation', () => {
    for (const [i, v] of (doc.vectors.subhandle_derivation ?? []).entries()) {
      it(`row ${i}: ${v.description}`, async () => {
        const identity = await Identity.fromSeed(fromHex(v.seed_hex as string));
        const atomic = await identity.deriveSubHandle(
          v.handle_name as string,
          v.sub_name as string
        );
        expect(hex(atomic.getPublicKey())).toBe(v.expected_public_key_hex);
        expect(atomic.getId()).toBe(v.expected_id_b64url);

        // Two-step parity: Handle.deriveSubHandle must produce the same key.
        const handle = await identity.deriveHandle(v.handle_name as string);
        const twoStep = await handle.deriveSubHandle(v.sub_name as string);
        expect(hex(twoStep.getPublicKey())).toBe(v.expected_public_key_hex);
      });
    }
  });

  describe('derive_password', () => {
    for (const [i, v] of (doc.vectors.derive_password ?? []).entries()) {
      it(`row ${i}: ${v.description}`, async () => {
        const identity = await Identity.fromSeed(fromHex(v.seed_hex as string));
        const handle = await identity.deriveHandle(v.handle_name as string);
        expect(handle.derivePassword(v.context as string, v.length as number))
          .toBe(v.expected_b64url);
      });
    }

    it('canonicalized context equals the canonical row (determinism)', async () => {
      const rows = doc.vectors.derive_password ?? [];
      const canonical = rows.find(r => r.context === 'github' && r.length === 16);
      const noisy = rows.find(r => r.context === '  GitHub ');
      expect(canonical && noisy).toBeTruthy();
      expect(canonical!.expected_b64url).toBe(noisy!.expected_b64url);
    });
  });

  describe('derive_channel_key', () => {
    for (const [i, v] of (doc.vectors.derive_channel_key ?? []).entries()) {
      it(`row ${i}: ${v.description}`, async () => {
        const identity = await Identity.fromSeed(fromHex(v.seed_hex as string));
        const handle = await identity.deriveHandle(v.handle_name as string);
        const key = handle.deriveChannelKey(v.context as string);
        expect(key.length).toBe(32);
        expect(hex(key)).toBe(v.expected_key_hex);
      });
    }
  });

  describe('derive_shared_secret', () => {
    for (const [i, v] of (doc.vectors.derive_shared_secret ?? []).entries()) {
      it(`row ${i}: ${v.description} (order-independent)`, async () => {
        const identity = await Identity.fromSeed(fromHex(v.seed_hex as string));
        const a = await identity.deriveHandle(v.handle_name_a as string);
        const b = await identity.deriveHandle(v.handle_name_b as string);
        const ab = await a.deriveSharedSecret(b.getPublicKey());
        const ba = await b.deriveSharedSecret(a.getPublicKey());
        expect(hex(ab)).toBe(v.expected_secret_hex);
        expect(hex(ba)).toBe(v.expected_secret_hex);
      });
    }
  });

  describe('attestation_handle (byte-deterministic)', () => {
    for (const [i, v] of (doc.vectors.attestation_handle ?? []).entries()) {
      it(`row ${i}: re-issue reproduces the token byte-for-byte`, async () => {
        const identity = await Identity.fromSeed(fromHex(v.seed_hex as string));
        const att = await identity.attestHandle(
          v.subject_handle_name as string,
          v.grant as Parameters<typeof identity.attestHandle>[1],
          {
            ttlSeconds: v.ttl_seconds as number,
            jti: v.jti as string,
            now: v.now as number,
          }
        );
        expect(att.token).toBe(v.expected_token);
        expect(JSON.stringify(att.payload)).toBe(v.expected_payload_json);
        expect(await Attestation.verifySignature(att.token, identity.getPublicKey()))
          .toBe(true);
      });
    }
  });

  describe('attestation_subhandle (byte-deterministic)', () => {
    for (const [i, v] of (doc.vectors.attestation_subhandle ?? []).entries()) {
      it(`row ${i}: re-issue reproduces the token byte-for-byte`, async () => {
        const identity = await Identity.fromSeed(fromHex(v.seed_hex as string));
        const handle = await identity.deriveHandle(v.subject_handle_name as string);
        const att = await handle.attestSubHandle(
          v.subject_sub_name as string,
          v.grant as Parameters<typeof handle.attestSubHandle>[1],
          {
            ttlSeconds: v.ttl_seconds as number,
            jti: v.jti as string,
            now: v.now as number,
          }
        );
        expect(att.token).toBe(v.expected_token);
        expect(JSON.stringify(att.payload)).toBe(v.expected_payload_json);
        expect(await Attestation.verifySignature(att.token, handle.getPublicKey()))
          .toBe(true);
      });
    }
  });

  for (const kind of ['session_handle', 'session_subhandle'] as const) {
    describe(`${kind} (pinned payload + Ed25519)`, () => {
      for (const [i, v] of (doc.vectors[kind] ?? []).entries()) {
        it(`row ${i}: ${v.description}`, async () => {
          const identity = await Identity.fromSeed(fromHex(v.seed_hex as string));
          const handle = await identity.deriveHandle(v.handle_name as string);
          const signer = kind === 'session_subhandle'
            ? await identity.deriveSubHandle(
                v.handle_name as string, v.sub_name as string)
            : handle;

          const payloadJson = v.expected_payload_json as string;
          const payloadBytes = new TextEncoder().encode(payloadJson);
          const payload = JSON.parse(payloadJson) as Record<string, unknown>;

          // hId in the vector must be the runtime-derived id
          expect(payload.hId).toBe(signer.getId());
          expect(payload.hNm).toBe(signer.getName());

          // Rebuild the token: Ed25519 over the exact pinned bytes
          const sig = await signer.sign(payloadBytes);
          const token = `${base64urlEncode(payloadBytes)}.${base64urlEncode(sig)}`;
          expect(token).toBe(v.expected_token);

          // Signature verifies against the derived public key
          const expectedSig = base64urlDecode(
            (v.expected_token as string).split('.')[1]
          );
          expect(await Handle.verify(expectedSig, payloadBytes, signer.getPublicKey()))
            .toBe(true);

          // Live smoke: same inputs through Session.create keep the same
          // canonical shape and pass verification end-to-end.
          const live = await Session.create(signer, {
            audience: v.audience as string,
            scopes: v.scopes as string[],
            ttl: v.ttl as number,
            sessionId: v.jti as string,
          });
          const livePayloadB64 = live.token.split('.')[0];
          const livePayload = JSON.parse(
            new TextDecoder().decode(base64urlDecode(livePayloadB64))
          ) as Record<string, unknown>;
          expect(Object.keys(livePayload)).toEqual(Object.keys(payload));
          expect(livePayload.hId).toBe(payload.hId);
          expect(livePayload.jti).toBe(payload.jti);
          expect((livePayload.exp as number) - (livePayload.iat as number))
            .toBe(v.ttl);
          const verified = await Session.verifyStateless(
            live.token, identity, v.audience as string
          );
          expect(verified.sessionId).toBe(v.jti);
        });
      }
    });
  }
});
